import React, { useState, useEffect, useMemo } from 'react';
import {
  Container,
  Typography,
  Box,
  Grid,
  Card,
  CardMedia,
  CardContent,
  Button,
  Chip,
  Alert,
  Skeleton,
  TextField,
  InputAdornment,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Badge,
  Drawer,
  List,
  ListItem,
  ListItemText,
  Divider,
  Slider,
  FormControlLabel,
  Checkbox,
  Fab,
  Snackbar
} from '@mui/material';
import { 
  ShoppingCart, 
  Favorite, 
  Visibility, 
  Search,
  FilterList,
  Close,
  GridView,
  ViewList,
  Sort
} from '@mui/icons-material';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';

const ProductsPage = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { addToCart, getCartCount } = useCart();
  const { isAuthenticated } = useAuth();
  
  const [searchQuery, setSearchQuery] = useState(searchParams.get('search') || '');
  const [selectedCategory, setSelectedCategory] = useState(searchParams.get('category') || 'all');
  const [showSaleOnly, setShowSaleOnly] = useState(searchParams.get('sale') === 'true');
  const [priceRange, setPriceRange] = useState([0, 500]);
  const [sortBy, setSortBy] = useState('name');
  const [viewMode, setViewMode] = useState('grid');
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [favorites, setFavorites] = useState([]);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [selectedSize, setSelectedSize] = useState({});
  const [selectedColor, setSelectedColor] = useState({});

  const categories = [
    'all', 'T-Shirts', 'Jackets', 'Dresses', 'Shoes', 'Accessories', 
    'Sweaters', 'Jeans', 'Shirts', 'Skirts', 'Bags', 'Jewelry'
  ];

  // Enhanced 20 products collection
  const sampleProducts = [
    // T-Shirts
    { _id: '1', name: 'Premium Cotton T-Shirt', price: 29.99, originalPrice: 39.99, sale: true, images: ['https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=400'], category: 'T-Shirts', description: 'Comfortable premium cotton t-shirt with superior quality', inStock: true, rating: 4.5, reviews: 124 },
    { _id: '2', name: 'Vintage Graphic Tee', price: 24.99, images: ['https://images.unsplash.com/photo-1503341504253-dff4815485f1?w=400'], category: 'T-Shirts', description: 'Retro-style graphic t-shirt with unique design', inStock: true, rating: 4.2, reviews: 89 },
    { _id: '3', name: 'Basic White Tee', price: 19.99, images: ['https://images.unsplash.com/photo-1562157873-818bc0726f68?w=400'], category: 'T-Shirts', description: 'Essential white t-shirt for everyday wear', inStock: true, rating: 4.7, reviews: 256 },
    
    // Jackets
    { _id: '4', name: 'Classic Denim Jacket', price: 89.99, originalPrice: 119.99, sale: true, images: ['https://images.unsplash.com/photo-1544022613-e87ca75a784a?w=400'], category: 'Jackets', description: 'Timeless denim jacket for any occasion', inStock: true, rating: 4.6, reviews: 198 },
    { _id: '5', name: 'Leather Biker Jacket', price: 199.99, images: ['https://images.unsplash.com/photo-1520975954732-35dd22299614?w=400'], category: 'Jackets', description: 'Edgy leather jacket with classic biker style', inStock: true, rating: 4.8, reviews: 87 },
    { _id: '6', name: 'Bomber Jacket', price: 79.99, images: ['https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=400'], category: 'Jackets', description: 'Trendy bomber jacket with modern fit', inStock: false, rating: 4.3, reviews: 156 },
    
    // Dresses
    { _id: '7', name: 'Elegant Summer Dress', price: 59.99, images: ['https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?w=400'], category: 'Dresses', description: 'Light and airy summer dress perfect for warm days', inStock: true, rating: 4.4, reviews: 203 },
    { _id: '8', name: 'Little Black Dress', price: 89.99, images: ['https://images.unsplash.com/photo-1566479179817-c2aa6c5e8a59?w=400'], category: 'Dresses', description: 'Classic little black dress for elegant occasions', inStock: true, rating: 4.9, reviews: 145 },
    { _id: '9', name: 'Floral Maxi Dress', price: 79.99, originalPrice: 99.99, sale: true, images: ['https://images.unsplash.com/photo-1572804013309-59a88b7e92f1?w=400'], category: 'Dresses', description: 'Beautiful floral maxi dress for special events', inStock: true, rating: 4.5, reviews: 167 },
    
    // Shoes
    { _id: '10', name: 'Casual Sneakers', price: 79.99, images: ['https://images.unsplash.com/photo-1549298916-b41d501d3772?w=400'], category: 'Shoes', description: 'Comfortable casual sneakers for daily wear', inStock: true, rating: 4.6, reviews: 312 },
    { _id: '11', name: 'Running Shoes', price: 119.99, images: ['https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=400'], category: 'Shoes', description: 'High-performance running shoes with excellent cushioning', inStock: true, rating: 4.7, reviews: 298 },
    { _id: '12', name: 'Elegant Heels', price: 99.99, images: ['https://images.unsplash.com/photo-1543163521-1bf539c55dd2?w=400'], category: 'Shoes', description: 'Sophisticated heels for formal occasions', inStock: true, rating: 4.3, reviews: 156 },
    
    // Accessories
    { _id: '13', name: 'Leather Handbag', price: 129.99, images: ['https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=400'], category: 'Accessories', description: 'Premium leather handbag with spacious interior', inStock: true, rating: 4.8, reviews: 189 },
    { _id: '14', name: 'Designer Sunglasses', price: 149.99, originalPrice: 199.99, sale: true, images: ['https://images.unsplash.com/photo-1511499767150-a48a237f0083?w=400'], category: 'Accessories', description: 'Stylish designer sunglasses with UV protection', inStock: true, rating: 4.6, reviews: 234 },
    { _id: '15', name: 'Silk Scarf', price: 39.99, images: ['https://images.unsplash.com/photo-1601924994987-69e26d50dc26?w=400'], category: 'Accessories', description: 'Luxurious silk scarf with elegant patterns', inStock: true, rating: 4.4, reviews: 98 },
    
    // Sweaters
    { _id: '16', name: 'Wool Blend Sweater', price: 69.99, images: ['https://images.unsplash.com/photo-1576566588028-4147f3842f27?w=400'], category: 'Sweaters', description: 'Cozy wool blend sweater for cooler weather', inStock: true, rating: 4.5, reviews: 178 },
    { _id: '17', name: 'Cashmere Cardigan', price: 159.99, images: ['https://images.unsplash.com/photo-1434389677669-e08b4cac3105?w=400'], category: 'Sweaters', description: 'Luxurious cashmere cardigan with soft texture', inStock: false, rating: 4.9, reviews: 134 },
    
    // Jeans
    { _id: '18', name: 'Slim Fit Jeans', price: 89.99, images: ['https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=400'], category: 'Jeans', description: 'Modern slim fit jeans with comfortable stretch', inStock: true, rating: 4.4, reviews: 267 },
    { _id: '19', name: 'High Waist Jeans', price: 79.99, originalPrice: 99.99, sale: true, images: ['https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?w=400'], category: 'Jeans', description: 'Trendy high waist jeans with flattering fit', inStock: true, rating: 4.6, reviews: 345 },
    
    // Additional item
    { _id: '20', name: 'Designer Watch', price: 249.99, images: ['https://images.unsplash.com/photo-1524592094714-0f0654e20314?w=400'], category: 'Accessories', description: 'Elegant designer watch with precision movement', inStock: true, rating: 4.8, reviews: 123 }
  ];

  // Filter and search logic
  const filteredProducts = useMemo(() => {
    let filtered = sampleProducts;

    // Filter by search query
    if (searchQuery) {
      filtered = filtered.filter(product => 
        product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        product.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        product.category.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    // Filter by category
    if (selectedCategory !== 'all') {
      filtered = filtered.filter(product => product.category === selectedCategory);
    }

    // Filter by price range
    filtered = filtered.filter(product => 
      product.price >= priceRange[0] && product.price <= priceRange[1]
    );

    // Sort products
    filtered.sort((a, b) => {
      switch (sortBy) {
        case 'price-low':
          return a.price - b.price;
        case 'price-high':
          return b.price - a.price;
        case 'rating':
          return (b.rating || 0) - (a.rating || 0);
        case 'name':
        default:
          return a.name.localeCompare(b.name);
      }
    });

    return filtered;
  }, [searchQuery, selectedCategory, priceRange, sortBy]);

  const handleAddToCart = (product) => {
    // Check if user needs to be authenticated for cart functionality
    if (!isAuthenticated) {
      navigate('/login', { state: { from: { pathname: '/products' } } });
      return;
    }

    const productSize = selectedSize[product._id] || product.size[0];
    const productColor = selectedColor[product._id] || product.color[0];

    try {
      addToCart(product, 1, productSize, productColor);
      setSnackbar({ 
        open: true, 
        message: `${product.name} (${productSize}, ${productColor}) added to cart!`, 
        severity: 'success' 
      });
    } catch (error) {
      setSnackbar({ 
        open: true, 
        message: error.message, 
        severity: 'error' 
      });
    }
  };

  const handleToggleFavorite = (productId) => {
    setFavorites(prev => {
      const isFavorite = prev.includes(productId);
      const newFavorites = isFavorite 
        ? prev.filter(id => id !== productId)
        : [...prev, productId];
      
      const product = sampleProducts.find(p => p._id === productId);
      setSnackbar({ 
        open: true, 
        message: `${product.name} ${isFavorite ? 'removed from' : 'added to'} favorites!`, 
        severity: 'info' 
      });
      
      return newFavorites;
    });
  };

  const handleViewProduct = (productId) => {
    navigate(`/products/${productId}`);
  };

  const handleSearchChange = (event) => {
    const value = event.target.value;
    setSearchQuery(value);
    const newParams = new URLSearchParams(searchParams);
    if (value) {
      newParams.set('search', value);
    } else {
      newParams.delete('search');
    }
    setSearchParams(newParams);
  };

  const handleCategoryChange = (category) => {
    setSelectedCategory(category);
    const newParams = new URLSearchParams(searchParams);
    if (category !== 'all') {
      newParams.set('category', category);
    } else {
      newParams.delete('category');
    }
    setSearchParams(newParams);
  };

  return (
    <Box>
      <Container maxWidth="xl" sx={{ py: { xs: 2, md: 4 } }}>
        {/* Page Header */}
        <Box sx={{ mb: 4 }}>
          <Typography 
            variant="h3" 
            gutterBottom 
            fontWeight="bold"
            sx={{
              fontSize: { xs: '2rem', md: '3rem' },
              background: 'linear-gradient(45deg, #667eea, #764ba2)',
              backgroundClip: 'text',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}
          >
            Our Products
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ fontSize: { xs: '0.9rem', md: '1rem' } }}>
            Discover our curated collection of {filteredProducts.length} fashion items
          </Typography>
        </Box>

        {/* Search and Filters Bar */}
        <Box sx={{ mb: 4 }}>
          <Grid container spacing={2} alignItems="center">
            {/* Search Bar */}
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                placeholder="Search products..."
                value={searchQuery}
                onChange={handleSearchChange}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <Search />
                    </InputAdornment>
                  ),
                }}
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: 2,
                  }
                }}
              />
            </Grid>

            {/* Category Filter */}
            <Grid item xs={6} md={2}>
              <FormControl fullWidth>
                <InputLabel>Category</InputLabel>
                <Select
                  value={selectedCategory}
                  label="Category"
                  onChange={(e) => handleCategoryChange(e.target.value)}
                  sx={{ borderRadius: 2 }}
                >
                  {categories.map((category) => (
                    <MenuItem key={category} value={category}>
                      {category === 'all' ? 'All Categories' : category}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {/* Sort By */}
            <Grid item xs={6} md={2}>
              <FormControl fullWidth>
                <InputLabel>Sort By</InputLabel>
                <Select
                  value={sortBy}
                  label="Sort By"
                  onChange={(e) => setSortBy(e.target.value)}
                  sx={{ borderRadius: 2 }}
                >
                  <MenuItem value="name">Name</MenuItem>
                  <MenuItem value="price-low">Price: Low to High</MenuItem>
                  <MenuItem value="price-high">Price: High to Low</MenuItem>
                  <MenuItem value="rating">Rating</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            {/* Filter Button (Mobile) */}
            <Grid item xs={6} md={2}>
              <Button
                fullWidth
                variant="outlined"
                startIcon={<FilterList />}
                onClick={() => setFiltersOpen(true)}
                sx={{ 
                  borderRadius: 2,
                  display: { md: 'none' }
                }}
              >
                Filters
              </Button>
            </Grid>

            {/* View Mode Toggle */}
            <Grid item xs={6} md={2}>
              <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                <IconButton
                  onClick={() => setViewMode('grid')}
                  color={viewMode === 'grid' ? 'primary' : 'default'}
                  sx={{
                    border: '1px solid',
                    borderColor: viewMode === 'grid' ? 'primary.main' : 'divider',
                    borderRadius: 1
                  }}
                >
                  <GridView />
                </IconButton>
                <IconButton
                  onClick={() => setViewMode('list')}
                  color={viewMode === 'list' ? 'primary' : 'default'}
                  sx={{
                    border: '1px solid',
                    borderColor: viewMode === 'list' ? 'primary.main' : 'divider',
                    borderRadius: 1
                  }}
                >
                  <ViewList />
                </IconButton>
              </Box>
            </Grid>
          </Grid>
        </Box>

        {/* Products Grid */}
        <Grid container spacing={viewMode === 'list' ? 2 : 3}>
          {filteredProducts.map((product) => (
            <Grid 
              item 
              xs={12} 
              sm={viewMode === 'list' ? 12 : 6} 
              md={viewMode === 'list' ? 12 : 4} 
              lg={viewMode === 'list' ? 12 : 3} 
              key={product._id}
            >
              <Card 
                sx={{ 
                  height: '100%',
                  display: 'flex',
                  flexDirection: viewMode === 'list' ? 'row' : 'column',
                  borderRadius: 3,
                  overflow: 'hidden',
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    transform: 'translateY(-8px)',
                    boxShadow: '0 20px 40px rgba(0,0,0,0.15)'
                  }
                }}
              >
                {/* Product Image */}
                <Box 
                  sx={{ 
                    position: 'relative',
                    width: viewMode === 'list' ? { xs: '120px', sm: '200px' } : '100%',
                    height: viewMode === 'list' ? 'auto' : '250px',
                    minHeight: viewMode === 'list' ? '120px' : 'auto'
                  }}
                >
                  <CardMedia
                    component="img"
                    height={viewMode === 'list' ? '100%' : '250'}
                    image={product.images[0]}
                    alt={product.name}
                    sx={{ 
                      objectFit: 'cover',
                      cursor: 'pointer',
                      transition: 'transform 0.3s ease'
                    }}
                    onClick={() => handleViewProduct(product._id)}
                  />
                  
                  {/* Sale Badge */}
                  {product.sale && (
                    <Chip
                      label="SALE"
                      size="small"
                      sx={{
                        position: 'absolute',
                        top: 8,
                        left: 8,
                        backgroundColor: '#FF6B35',
                        color: 'white',
                        fontWeight: 'bold'
                      }}
                    />
                  )}
                  
                  {/* Stock Status */}
                  {!product.inStock && (
                    <Chip
                      label="Out of Stock"
                      color="error"
                      size="small"
                      sx={{
                        position: 'absolute',
                        top: 8,
                        left: 8
                      }}
                    />
                  )}

                  {/* Quick Actions */}
                  <Box
                    sx={{
                      position: 'absolute',
                      top: 8,
                      right: 8,
                      display: 'flex',
                      flexDirection: 'column',
                      gap: 1,
                      opacity: { xs: 1, md: 0 },
                      transition: 'opacity 0.2s ease-in-out',
                      '.MuiCard-root:hover &': {
                        opacity: 1
                      }
                    }}
                  >
                    <IconButton
                      size="small"
                      sx={{ 
                        backgroundColor: 'rgba(255, 255, 255, 0.9)',
                        color: 'primary.main',
                        '&:hover': {
                          backgroundColor: 'white',
                          transform: 'scale(1.1)'
                        }
                      }}
                      onClick={() => handleViewProduct(product._id)}
                    >
                      <Visibility fontSize="small" />
                    </IconButton>
                    <IconButton
                      size="small"
                      sx={{ 
                        backgroundColor: 'rgba(255, 255, 255, 0.9)',
                        color: favorites.includes(product._id) ? 'error.main' : 'grey.500',
                        '&:hover': {
                          backgroundColor: 'white',
                          transform: 'scale(1.1)'
                        }
                      }}
                      onClick={() => handleToggleFavorite(product._id)}
                    >
                      <Favorite fontSize="small" />
                    </IconButton>
                  </Box>
                </Box>

                {/* Product Info */}
                <CardContent 
                  sx={{ 
                    flexGrow: 1, 
                    display: 'flex', 
                    flexDirection: 'column',
                    p: viewMode === 'list' ? { xs: 2, sm: 3 } : 3
                  }}
                >
                  <Box sx={{ mb: 2 }}>
                    <Typography 
                      variant={viewMode === 'list' ? 'h6' : 'h6'} 
                      gutterBottom 
                      fontWeight="bold" 
                      sx={{ 
                        cursor: 'pointer',
                        '&:hover': { color: 'primary.main' },
                        fontSize: viewMode === 'list' ? { xs: '1rem', sm: '1.25rem' } : '1.25rem'
                      }}
                      onClick={() => handleViewProduct(product._id)}
                    >
                      {product.name}
                    </Typography>
                    
                    <Typography 
                      variant="body2" 
                      color="text.secondary" 
                      sx={{ 
                        mb: 1, 
                        display: '-webkit-box',
                        WebkitLineClamp: viewMode === 'list' ? 2 : 2,
                        WebkitBoxOrient: 'vertical',
                        overflow: 'hidden'
                      }}
                    >
                      {product.description}
                    </Typography>

                    {/* Rating */}
                    {product.rating && (
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                        <Box sx={{ display: 'flex', color: '#ffc107' }}>
                          {[...Array(5)].map((_, i) => (
                            <Typography key={i} sx={{ fontSize: '1rem' }}>
                              {i < Math.floor(product.rating) ? '★' : '☆'}
                            </Typography>
                          ))}
                        </Box>
                        <Typography variant="body2" color="text.secondary">
                          {product.rating} ({product.reviews} reviews)
                        </Typography>
                      </Box>
                    )}
                  </Box>

                  <Box sx={{ mt: 'auto' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                      <Chip 
                        label={product.category} 
                        variant="outlined" 
                        size="small"
                        color="primary"
                        sx={{ fontSize: '0.75rem' }}
                      />
                      <Box>
                        {product.originalPrice && product.sale && (
                          <Typography 
                            variant="body2" 
                            sx={{ 
                              textDecoration: 'line-through',
                              color: 'text.secondary',
                              mr: 1,
                              display: 'inline'
                            }}
                          >
                            ${product.originalPrice}
                          </Typography>
                        )}
                        <Typography 
                          variant="h6" 
                          fontWeight="bold" 
                          color="primary.main"
                          sx={{ display: 'inline' }}
                        >
                          ${product.price}
                        </Typography>
                      </Box>
                    </Box>

                    <Button
                      variant="contained"
                      fullWidth
                      startIcon={<ShoppingCart />}
                      disabled={!product.inStock}
                      onClick={() => handleAddToCart(product)}
                      sx={{ 
                        borderRadius: 2,
                        py: 1.2,
                        fontWeight: 600,
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          transform: 'translateY(-1px)',
                          boxShadow: '0 6px 20px rgba(102, 126, 234, 0.4)'
                        }
                      }}
                    >
                      {product.inStock ? 'Add to Cart' : 'Out of Stock'}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* Mobile Filters Drawer */}
        <Drawer
          anchor="right"
          open={filtersOpen}
          onClose={() => setFiltersOpen(false)}
          sx={{ display: { md: 'none' } }}
        >
          <Box sx={{ width: 300, p: 3 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3 }}>
              <Typography variant="h6" fontWeight="bold">Filters</Typography>
              <IconButton onClick={() => setFiltersOpen(false)}>
                <Close />
              </IconButton>
            </Box>
            
            <Divider sx={{ mb: 3 }} />
            
            {/* Price Range */}
            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
              Price Range
            </Typography>
            <Slider
              value={priceRange}
              onChange={(_, newValue) => setPriceRange(newValue)}
              valueLabelDisplay="auto"
              min={0}
              max={500}
              sx={{ mb: 3 }}
            />
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
              ${priceRange[0]} - ${priceRange[1]}
            </Typography>
            
            <Divider sx={{ mb: 3 }} />
            
            {/* Category Filter for Mobile */}
            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
              Categories
            </Typography>
            <List>
              {categories.map((category) => (
                <ListItem key={category} button onClick={() => handleCategoryChange(category)}>
                  <Checkbox 
                    checked={selectedCategory === category}
                    sx={{ mr: 1 }}
                  />
                  <ListItemText primary={category === 'all' ? 'All Categories' : category} />
                </ListItem>
              ))}
            </List>
          </Box>
        </Drawer>

        {/* Floating Cart Button */}
        {isAuthenticated && getCartCount() > 0 && (
          <Fab
            color="primary"
            sx={{
              position: 'fixed',
              bottom: 20,
              right: 20,
              zIndex: 1000
            }}
            onClick={() => navigate('/cart')}
          >
            <Badge badgeContent={getCartCount()} color="error">
              <ShoppingCart />
            </Badge>
          </Fab>
        )}

        {/* Snackbar for notifications */}
        <Snackbar
          open={snackbar.open}
          autoHideDuration={3000}
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
          message={snackbar.message}
        />

        {/* Empty State */}
        {filteredProducts.length === 0 && (
          <Box
            sx={{
              textAlign: 'center',
              py: 12,
              gridColumn: '1 / -1'
            }}
          >
            <Typography variant="h4" gutterBottom color="text.secondary" fontWeight="bold">
              No products found
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
              {searchQuery 
                ? `No products match "${searchQuery}"` 
                : selectedCategory !== 'all'
                  ? `No products in "${selectedCategory}" category`
                  : 'No products available right now'
              }
            </Typography>
            <Button 
              variant="outlined" 
              onClick={() => {
                setSearchQuery('');
                setSelectedCategory('all');
                setPriceRange([0, 500]);
              }}
              sx={{ borderRadius: 2 }}
            >
              Clear Filters
            </Button>
          </Box>
        )}
      </Container>
    </Box>
  );
};

export default ProductsPage;
